using System;
using System.Collections.Generic;
using System.Linq;
using System.Linq.Expressions;
using System.Reflection;

namespace ReflectionDemo
{
    // -- 自定义特性 --
    [AttributeUsage(AttributeTargets.Class | AttributeTargets.Property, AllowMultiple = false)]
    public class CacheAttribute : Attribute
    {
        public int Duration { get; }
        public string Region { get; set; }
        public CacheAttribute(int duration) => Duration = duration;
    }

    [AttributeUsage(AttributeTargets.Property)]
    public class RequiredAttribute : Attribute
    {
        public string ErrorMessage { get; set; }
    }

    [AttributeUsage(AttributeTargets.Property)]
    public class MaxLengthAttribute : Attribute
    {
        public int Length { get; }
        public MaxLengthAttribute(int length) => Length = length;
    }

    // -- 被标注的实体 --
    [Cache(300, Region = "users")]
    public class User
    {
        [Required(ErrorMessage = "ID 不能为空")]
        public int Id { get; set; }

        [Required(ErrorMessage = "姓名不能为空")]
        [MaxLength(50)]
        public string Name { get; set; }

        [MaxLength(100)]
        public string Email { get; set; }

        [Cache(60)]
        public string GetDisplayName() => $"{Name} ({Id})";
    }

    // -- 反射工具（带缓存） --
    public static class ReflectionHelper
    {
        private static readonly Dictionary<Type, PropertyInfo[]> Cache = new();

        public static PropertyInfo[] GetPropertiesCached(Type type)
        {
            // ConcurrentDictionary 更好，这里用 Dictionary 简化演示
            if (!Cache.TryGetValue(type, out var props))
            {
                props = type.GetProperties(BindingFlags.Public | BindingFlags.Instance);
                Cache[type] = props;
            }
            return props;
        }

        public static List<string> Validate(object obj)
        {
            var errors = new List<string>();
            foreach (var prop in GetPropertiesCached(obj.GetType()))
            {
                var req = prop.GetCustomAttribute<RequiredAttribute>();
                if (req != null)
                {
                    var val = prop.GetValue(obj);
                    if (val == null || string.IsNullOrWhiteSpace(val.ToString()))
                        errors.Add(req.ErrorMessage ?? $"{prop.Name} 不能为空");
                }
                var ml = prop.GetCustomAttribute<MaxLengthAttribute>();
                if (ml != null && prop.PropertyType == typeof(string))
                {
                    var val = prop.GetValue(obj) as string;
                    if (val != null && val.Length > ml.Length)
                        errors.Add($"{prop.Name} 长度不能超过 {ml.Length}");
                }
            }
            return errors;
        }
    }

    // -- Expression Tree：动态属性访问器 --
    public static class ExpressionHelper
    {
        // 编译一次，反复使用
        private static readonly Dictionary<string, Delegate> AccessorCache = new();

        public static Func<T, object> GetAccessor<T>(string propertyName)
        {
            var key = typeof(T).FullName + "." + propertyName;
            if (AccessorCache.TryGetValue(key, out var cached))
                return (Func<T, object>)cached;

            var param = Expression.Parameter(typeof(T), "x");
            var body = Expression.Convert(Expression.Property(param, propertyName), typeof(object));
            var lambda = Expression.Lambda<Func<T, object>>(body, param);
            var compiled = lambda.Compile();
            AccessorCache[key] = compiled;
            return compiled;
        }

        // 动态 LINQ 排序（用于 IQueryable）
        public static IQueryable<T> OrderByDynamic<T>(
            IQueryable<T> source, string propertyName, bool ascending = true)
        {
            var param = Expression.Parameter(typeof(T), "x");
            var body = Expression.Property(param, propertyName);
            var lambda = Expression.Lambda(body, param);

            var method = typeof(Queryable).GetMethods()
                .First(m => m.Name == (ascending ? "OrderBy" : "OrderByDescending")
                            && m.GetParameters().Length == 2)
                .MakeGenericMethod(typeof(T), body.Type);

            return (IQueryable<T>)method.Invoke(null, new object[] { source, lambda });
        }
    }

    class Program
    {
        static void Main()
        {
            var user = new User { Id = 1, Name = "Alice", Email = "alice@example.com" };

            // 1. 验证
            var errors = ReflectionHelper.Validate(user);
            Console.WriteLine($"验证错误数: {errors.Count}"); // 0

            // 2. 读取类级 Attribute
            var cacheAttr = typeof(User).GetCustomAttribute<CacheAttribute>();
            Console.WriteLine($"缓存: {cacheAttr.Duration}s, 区域: {cacheAttr.Region}"); // 300, users

            // 3. Expression Tree 属性访问器（编译后性能接近直接访问）
            var nameAccessor = ExpressionHelper.GetAccessor<User>("Name");
            Console.WriteLine($"Name = {nameAccessor(user)}"); // Alice

            // 4. 无效对象验证
            var bad = new User { Id = 0, Name = "", Email = new string('x', 200) };
            var badErrors = ReflectionHelper.Validate(bad);
            Console.WriteLine($"Bad errors: {string.Join(", ", badErrors)}");
        }
    }
}
